// Memory-only authority from the existing venue unlock. No PIN or person identity is retained.
const API_BASE = process.env.REACT_APP_API_URL || '';
const ACCESS_MS = 300000;
const SESSION_MS = 12 * 60 * 60 * 1000;
let staff = null;
let admin = null;
let deadline;
// Interpret response deadlines against server time, independent of device clock skew.
let serverOffset = 0;
const serverNow = () => Date.now() + serverOffset;
const timers = new Map();
const requests = new Map();
const epoch = { staff: 0, admin: 0 };
const lockListeners = new Set();
const get = role => role === 'admin' ? admin : staff;
const ended = () => new Error('Venue access has ended. Use the existing venue unlock.');

function clearRole(role) {
  if (role === 'admin') admin = null; else staff = null;
  clearTimeout(timers.get(role)); timers.delete(role);
}
export function clearReviewAccess() {
  epoch.staff += 1; epoch.admin += 1;
  requests.clear(); clearTimeout(deadline); serverOffset = 0;
  clearRole('staff'); clearRole('admin');
}
export function endVenueAccess() {
  clearReviewAccess();
  for (const listener of lockListeners) { try { listener(); } catch {} }
}
export function subscribeVenueLock(listener) {
  lockListeners.add(listener);
  return () => lockListeners.delete(listener);
}
export function dropAdminReviewAccess() { epoch.admin += 1; requests.delete('admin'); clearRole('admin'); }
export function reviewEpoch(role) { return epoch[role]; }

function schedule(role, delay = 240000) {
  clearTimeout(timers.get(role));
  timers.set(role, setTimeout(() => { void renew(role).catch(() => {}); }, delay));
}
function scheduleDeadline() {
  clearTimeout(deadline);
  if (!staff) return;
  deadline = setTimeout(() => {
    if (staff && staff.sessionExpiresAt <= serverNow()) endVenueAccess();
    else scheduleDeadline();
  }, Math.max(0, staff.sessionExpiresAt - serverNow()));
}
function valid(grant) {
  return grant && typeof grant.token === 'string' && !!grant.token && grant.token.length <= 2048 &&
    typeof grant.renewalToken === 'string' && !!grant.renewalToken && grant.renewalToken.length <= 2048 &&
    ['staff', 'admin'].includes(grant.role) && Number.isFinite(grant.expiresAt) &&
    Number.isFinite(grant.sessionExpiresAt) && Number.isSafeInteger(grant.serverNow) &&
    grant.expiresAt > grant.serverNow && grant.expiresAt <= grant.serverNow + ACCESS_MS &&
    grant.sessionExpiresAt > grant.serverNow && grant.sessionExpiresAt <= grant.serverNow + SESSION_MS &&
    grant.expiresAt <= grant.sessionExpiresAt;
}
export function acceptReviewAccess(data, expectedEpoch, expectedRole) {
  const grant = data?.reviewAccess;
  if ((expectedRole && grant?.role !== expectedRole) ||
      (expectedEpoch !== undefined && epoch[grant?.role] !== expectedEpoch) || !valid(grant)) return false;
  if (grant.role === 'staff') {
    clearReviewAccess(); serverOffset = grant.serverNow - Date.now(); staff = grant; scheduleDeadline();
  } else {
    if (!staff || grant.sessionExpiresAt !== staff.sessionExpiresAt) return false;
    serverOffset = grant.serverNow - Date.now(); admin = grant; scheduleDeadline();
  }
  schedule(grant.role); return true;
}
async function renew(role) {
  const grant = get(role);
  if (!grant) return false;
  if (grant.sessionExpiresAt <= serverNow()) { endVenueAccess(); throw ended(); }
  if (requests.has(role)) return requests.get(role);
  const generation = epoch[role];
  const pending = (async () => {
    try {
      const res = await fetch(`${API_BASE}/api/v1/staff-review/renew`, {
        method: 'POST', credentials: 'omit', cache: 'no-store', redirect: 'error', referrerPolicy: 'no-referrer',
        headers: { Authorization: `Bearer ${grant.renewalToken}` },
      });
      if (generation !== epoch[role]) return false;
      if (!res.ok) {
        if (res.status === 401 || res.status === 403) { endVenueAccess(); throw ended(); }
        throw new Error('Booking review is temporarily unavailable. Try again when online.');
      }
      const data = await res.json().catch(() => null);
      if (generation !== epoch[role]) return false;
      const fresh = data?.reviewAccess;
      if (!valid(fresh) || fresh.role !== role || fresh.sessionExpiresAt !== grant.sessionExpiresAt ||
          fresh.renewalToken !== grant.renewalToken) { endVenueAccess(); throw ended(); }
      serverOffset = fresh.serverNow - Date.now();
      if (role === 'admin') admin = fresh; else { staff = fresh; scheduleDeadline(); }
      schedule(role); return true;
    } catch (err) {
      if (generation === epoch[role]) schedule(role, 15000);
      throw err;
    }
  })().finally(() => { if (requests.get(role) === pending) requests.delete(role); });
  requests.set(role, pending);
  return pending;
}
export async function resumeReviewAccess() {
  if (staff && staff.sessionExpiresAt <= serverNow()) { endVenueAccess(); return; }
  scheduleDeadline();
  await Promise.all(['staff', 'admin'].filter(role => get(role)).map(role => renew(role)));
}
export function reviewHeaders({ staffOnly = false } = {}) {
  const grant = (!staffOnly && admin) || staff;
  return grant && grant.expiresAt > serverNow() && grant.sessionExpiresAt > serverNow()
    ? { Authorization: `Bearer ${grant.token}` } : {};
}
export async function readyReviewHeaders({ staffOnly = false, required = false } = {}) {
  const role = !staffOnly && admin ? 'admin' : 'staff';
  const grant = get(role);
  if (!grant) { if (required) { endVenueAccess(); throw ended(); } return {}; }
  const generation = epoch[role];
  if (grant.sessionExpiresAt <= serverNow()) { endVenueAccess(); throw ended(); }
  if (grant.expiresAt <= serverNow() + 30000) await renew(role);
  if (generation !== epoch[role] || !get(role)) throw new Error('Venue access changed.');
  return reviewHeaders({ staffOnly });
}
export async function reviewFetch(url, options = {}, { required = false } = {}) {
  const role = admin ? 'admin' : 'staff';
  let headers = await readyReviewHeaders({ required });
  const generation = epoch[role];
  const send = () => fetch(url, { ...options, credentials: 'omit', cache: 'no-store', redirect: 'error', referrerPolicy: 'no-referrer',
    headers: { ...(options.headers || {}), ...headers } });
  let res = await send();
  if (res.status === 401 && typeof res.clone === 'function') {
    const data = await res.clone().json().catch(() => null);
    if (data?.error === 'STAFF_REVIEW_REQUIRED') {
      // This rejection occurs before mutation. Never replay an ambiguous network error.
      if (!get(role)) { endVenueAccess(); throw ended(); }
      await renew(role);
      if (generation !== epoch[role]) throw ended();
      headers = reviewHeaders(); res = await send();
      if (res.status === 401) { endVenueAccess(); throw ended(); }
    }
  }
  if (generation !== epoch[role]) throw new Error('Venue access changed.');
  return res;
}
