import { clearReviewAccess, dropAdminReviewAccess, subscribeVenueLock, resumeReviewAccess } from '../../common/api/bookingReviewAccess';
import { useAppState } from '../../app/providers';
import React, { useCallback, useState, useEffect } from "react";
import LockScreen from "./LockScreen";
import { isE2EMode } from "../../state/e2eMode";

/**
 * In-memory kiosk lock. Unlock does not survive refresh or reload.
 * Playwright may pass ?e2e=1 outside production builds.
 */
export default function SiteLockGate({ children }) {
  const [unlocked, setUnlocked] = useState(() => process.env.NODE_ENV === "test" || isE2EMode());
  const logout = useAppState(s => s.logout);
  const userRole = useAppState(s => s.userRole);
  useEffect(() => { if (userRole !== 'admin') dropAdminReviewAccess(); }, [userRole]);
  useEffect(() => subscribeVenueLock(() => {
    setUnlocked(false);
    logout?.();
  }), [logout]);
  useEffect(() => {
    const resume = () => {
      if (document.visibilityState === 'visible') void resumeReviewAccess().catch(() => {});
    };
    window.addEventListener('focus', resume);
    window.addEventListener('online', resume);
    document.addEventListener('visibilitychange', resume);
    return () => {
      window.removeEventListener('focus', resume);
      window.removeEventListener('online', resume);
      document.removeEventListener('visibilitychange', resume);
      clearReviewAccess();
    };
  }, []);
  const handleUnlock = useCallback(() => setUnlocked(true), []);

  if (!unlocked) {
    return <LockScreen onUnlock={handleUnlock} />;
  }

  return children;
}
